The GIR  defined in \eqref{hkdefine} can be expressed in terms of $E_k$ and $d_k$ as follows
	\begin{equation}
		h_k = d_k^TE_k^{-1}d_k	\label{hk}
	\end{equation}

\begin{equation}
		\begin{aligned}
			h_k &= \sum_{j = 1}^{k}\lVert \epsilon_j \rVert^2_{\varSigma_j^{-1}} - {\sum_{j = 1}^{k}\lVert \epsilon_j^0 \rVert^2_{\varSigma_j^{-1}}} \\
			&= \sum_{j = 1}^{k}\epsilon_j^T\varSigma_j^{-1}\epsilon_j \\
			&\quad - \sum_{j = 1}^{k} {\left( \epsilon_j - C_j\varGamma_j\hat{\theta}_k \right)}^T \varSigma_j^{-1} \left( \epsilon_j - C_j\varGamma_j \hat{\theta}_k \right) \\
			&= \sum_{j = 1}^{k} \left( 2\epsilon_j^T\varSigma_j^{-1}C_j\varGamma_j\hat{\theta}_k - \hat{\theta}_k^T\varGamma_j^T C_j^T\varSigma_j^{-1}C_j\varGamma_j\hat{\theta}_k\right) \\
		\end{aligned}
		\label{lk}
	\end{equation}
	where $\theta$ is assumed to be a constant fault vector in \eqref{statefault}, $E_k$ is a symmetric matrix. From \eqref{thetak}, so the \eqref{lk} can be rewritten
	\begin{equation}
		\begin{aligned}
			h_k &= 2\left( \sum_{j = 1}^{k} \epsilon_j^T\varSigma_j^{-1}C_j\varGamma_j \right)E_k^{-1}d_k \\
			&\quad - d_k^TE_k^{-1} \left( \sum_{j = 1}^{k} \varGamma_j^T C_j^T\varSigma_j^{-1}C_j\varGamma_j \right) E_k^{-1}d_k \\
			&= d_k^TE_k^{-1}d_k
		\end{aligned}
	\end{equation}
